 // Instrument the native popup without suppressing original presentation or replacing callbacks.
 const contextSpy = async () => H.app.evaluate(({Menu})=>{if(global.__servicesPopup)return;const old=Menu.prototype.popup;Menu.prototype.popup=function(...a){global.__servicesPopupMenu=this;return old.apply(this,a)};global.__servicesPopup={old};const prior=global.__servicesRestoreCase;global.__servicesRestoreCase=()=>{Menu.prototype.popup=old;delete global.__servicesPopup;delete global.__servicesPopupMenu;prior?.();global.__servicesRestoreCase=undefined;};});
 const context = async route => {const c=H.cases.find(c=>c.id===H.currentCase);if(c&&!c.routes.some(r=>JSON.stringify(r)===JSON.stringify(['context',...route])))c.routes.push(['context',...route]);
  await H.app.evaluate(()=>{global.__servicesPopupMenu=null;});const pos=await P().evaluate(()=>{const s=getSelection();if(!s.rangeCount)return null;const r=s.getRangeAt(0).getBoundingClientRect();return{x:r.x+Math.max(1,r.width/2),y:r.y+Math.max(1,r.height/2)};});H.assert(pos,'Context action needs a real selection');await P().mouse.click(pos.x,pos.y,{button:'right'});
  await H.wait(()=>H.app.evaluate(()=>Boolean(global.__servicesPopupMenu)));
  const r=await H.app.evaluate(({BrowserWindow},{route,wid})=>{let m=global.__servicesPopupMenu,x;for(const l of route){x=m.items.find(i=>i.label===l);if(!x)return{found:false};m=x.submenu;}const w=BrowserWindow.fromId(wid);global.__servicesPopupMenu.closePopup(w);if(!x.enabled)return{found:true,enabled:false};x.click(undefined,w);return{found:true,enabled:true};},{route,wid:H.windowId});H.assert(r.found&&r.enabled,'Native contextual route unavailable '+route.join(' > '));
 };

 // AI panel: all eight actions independently in missing-key, empty-input and successful-result states.
 for(const [action,label]of ACTIONS){
  add('ai.no-key.'+action,'AiPanel',label,{kind:'precondition',commands:['ai'],setup:async()=>open('ai'),act:async()=>{H.assert(await button(ai(),label).isDisabled(),label+' must require configuration');await ai().getByRole('textbox').fill('Întrebare fixture');},verify:async()=>{H.assert(await button(ai(),label).isDisabled(),'Action unexpectedly enabled');H.assert(await button(ai(),'Întreabă').isDisabled(),'Ask must require key');H.assert((await text(ai())).includes('furnizor AI configurat'),'Missing remediation note');await sameDoc();}});
  add('ai.empty.'+action,'AiPanel',label+' / document gol',{kind:'precondition',commands:['ai'],setup:async()=>{await sourceDoc('<p></p>');await configured();await open('ai');},act:async()=>button(ai(),label).click(),verify:async()=>{await H.wait(async()=>/Documentul e gol/.test(await text(ai().locator('[role=alert]'))));H.assert((await reqs()).length===0,'Empty text sent to provider');await sameDoc('<p></p>');}});
  add('ai.result.'+action,'AiPanel',label+' → rezultat și aplicare',{kind:'adapter',commands:['ai','save'],setup:async()=>{await configured({output:'Rezultat sintetic verificat.'});await open('ai');await remember();},act:async()=>{await runAi(label);const r=ai().locator('.ai-result');H.assert((await text(r)).includes('Rezultat sintetic verificat.'),'Wrong result text');await clipped(r);await button(r,'Copiază').click();H.assert(await copyText()==='Rezultat sintetic verificat.','Wrong clipboard');if(action==='proofread'||action==='translate')await button(r,'Acceptă (înlocuiește documentul)').click();else if(action==='continue')await button(r,'Inserează').click();else if(action==='summarize')await button(r,'Pune ca sinopsis în Inspector').click();else await button(r,'Închide').click();},verify:async()=>{const rr=await reqs();H.assert(rr.length===1&&rr[0].type==='ai','Action did not use real provider transport');H.assert(rr[0].body.includes('qa-synthetic'),'Configured model not dispatched');await H.save();if(action==='proofread'||action==='translate')H.assert(/<p>Rezultat sintetic verificat\.<\/p>/.test(H.doc()),'Replacement HTML missing');else if(action==='continue')H.assert(H.doc().includes('Rezultat sintetic verificat.')&&H.doc().includes('Prima frază'),'Continuation lost original');else if(action==='summarize')H.assert(H.node('doc-a').synopsis==='Rezultat sintetic verificat.','Synopsis not persisted');else H.assert(H.doc()===H.__svcBefore,'Read-only result mutated manuscript');H.assert(!await visible(ai().locator('.ai-result')),'Result not dismissed');}});
 }
 add('ai.configure.remedy','AiPanel','Deschide AI → Setări AI',{commands:['ai','aiSettings'],setup:async()=>open('ai'),act:async()=>{await button(ai(),'Deschide AI → Setări AI').click();await H.wait(()=>visible(H.modal().getByRole('heading',{name:'Setări AI program',exact:true})));},verify:async()=>{H.assert(await H.modal().getByLabel('Furnizor',{exact:true}).count()===1,'Not program provider context');H.assert(!await H.modal().locator('.project-ai-dialog').count(),'Wrong project context');await button(H.modal(),'Anulează').click();H.assert(await visible(ai()),'No return to assistant');await sameDoc();}});
